// adminCSS is the shared Tailwind stylesheet for every manager page
// (admin + login). Generated by the Tailwind CLI from
// internal/handlers/static/src.css (see api/Makefile `make css-build`).
// The source file `static/app.css` is gitignored; this embed pulls the
// generated output into the binary at compile time.
//
// Why embed + inline (vs serving as a separate `/static/app.css`): the
// admin tool has few concurrent users and the CSS is small (~16KB
// minified). Inlining keeps the request model as one HTML response and
// avoids an extra route/handler. If the CSS ever grows beyond ~50KB we
// can switch to a separate file served from a route.
//
//go:embed static/app.css
var adminCSS []byte

// chromeHeader is the shared <header> block (the green bar with nav).
// Each page template includes it via the chrome funcMap.
const chromeHeader = `
<header class="app-header">
  <h1><a href="/admin/">slimwhats</a></h1>
  <div class="nav">
    <a href="/admin/">Instances</a>
    <a href="/admin/audit">Audit</a>
    <a href="/swagger" target="_blank" rel="noopener noreferrer">Swagger</a>
    <form class="inline" method="POST" action="/admin/logout"><button class="btn secondary btn-sm">Logout</button></form>
  </div>
</header>
`

// chromeFunc is the FuncMap entry that wraps a page body in the full
// admin layout. Each page template calls it as {{chrome .Body}}.
//
// Why this approach (vs the old "adminLayout template + {{define "content"}}"
// pattern): Go's html/template shares the parse tree across templates
// that descend from the same parent, so multiple `{{define "content"}}`
// blocks all overwrite each other — only the last-defined one wins,
// which made every page render the audit page. Inlining the chrome
// via a FuncMap sidesteps the shared-tree issue entirely.
func chromeFunc(title string, body template.HTML) (template.HTML, error) {
	out := fmt.Sprintf(`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>slimwhats — %s</title>
<style>%s</style>
</head>
<body>
%s
<main>%s</main>
</body>
</html>`, title, string(adminCSS), chromeHeader, string(body))
	return template.HTML(out), nil
}

// adminFuncs is the FuncMap shared by all admin page templates.
var adminFuncs = template.FuncMap{
	"chrome": chromeFunc,
}

